import {t,esc,n,date,name,btn,table,panel,tag,field,select,area,show,api,toast,prefs} from './ui.mjs';import {available} from './core.mjs';import {icon} from './icons.mjs';import {features} from './features.mjs';
export function pathName(s,id){let seen=new Set(),names=[];while(id&&!seen.has(id)){seen.add(id);let l=s.locations.find(l=>l.id===id);if(!l)break;names.unshift(name(l));id=l.parent}return names.join(' / ')}
export function replenishment(s,wh=''){let rows=[];for(let p of s.products.filter(p=>p.active)){let rules=s.reorderRules.filter(r=>r.product===p.id&&(!wh||r.warehouse===wh));if(!rules.length)rules=[{warehouse:wh,min:p.min,target:p.target,safety:0}];for(let rule of rules){let avail=available(s,p.id,rule.warehouse),incoming=s.orders.filter(o=>o.kind==='purchase'&&!['cancelled','received'].includes(o.status)&&(!rule.warehouse||o.warehouse===rule.warehouse)).flatMap(o=>o.lines).filter(l=>l.product===p.id).reduce((q,l)=>q+l.qty-l.received,0);rows.push({product:p,rule,available:avail,incoming,suggest:Math.max(0,rule.target+(rule.safety||0)-avail-incoming),low:avail<=rule.min})}}return rows}
export function extraView(page,ctx){const {state:s,meta,me,can}=ctx;
if(page==='dashboard')return dashboardView(ctx);
if(page==='variants')return panel('variants',table(['product','group','attributeSummary','action'],s.products.map(p=>`<tr><td><b>${esc(name(p))}</b><small>${esc(p.sku)}</small></td><td>${esc(p.group||'—')}</td><td>${Object.entries(p.attributes).map(([k,v])=>`<span class="tag gray">${esc(k)}: ${esc(v)}</span>`).join(' ')||'—'}</td><td>${can('product_update')?btn('edit','product_update',p.id):''}</td></tr>`)));
if(page==='replenishment')return panel('replenishment',table(['product','warehouse','min','target','safety','leadDays','available','suggested','action'],replenishment(s).map(x=>`<tr><td><b>${esc(name(x.product))}</b><small>${esc(x.product.sku)}</small></td><td>${x.rule.warehouse?esc(name(s.warehouses.find(w=>w.id===x.rule.warehouse))):t('all')}</td><td>${n(x.rule.min)}</td><td>${n(x.rule.target)}</td><td>${n(x.rule.safety||0)}</td><td>${n(x.rule.leadDays||0)}</td><td>${n(x.available)} ${x.low?tag('low'):''}</td><td>${n(x.suggest)}</td><td>${can('reorder_rule')?btn('edit','reorder_rule',x.product.id+'|'+(x.rule.warehouse||'')):''}</td></tr>`)));
if(page==='supplierReturns')return panel('supplierReturns',table(['product','supplier','warehouse','qty','reason','at'],s.supplierReturns.map(x=>`<tr><td>${esc(name(s.products.find(p=>p.id===x.product)))}</td><td>${esc(s.contacts.find(c=>c.id===x.supplier)?.name)}</td><td>${esc(name(s.warehouses.find(w=>w.id===x.warehouse)))}</td><td>${n(x.qty)}</td><td>${esc(x.reason)}</td><td>${date(x.at)}</td></tr>`)));
if(page==='warehouses')return `<div class="cards">${s.warehouses.map(w=>`<article class="card"><span class="product-icon">${icon('warehouses')}</span><h3>${esc(name(w))}</h3><p>${esc(w.location)}</p><div class="detail-total"><span class="tag">${n(new Set(s.stock.filter(b=>b.warehouse===w.id&&b.qty>0).map(b=>b.product)).size)} ${t('product')}</span><span class="tag gray">${n(s.locations.filter(l=>l.warehouse===w.id).length)} ${t('location')}</span></div></article>`).join('')}</div><br>${panel('warehouses',`<div class="details">${s.warehouses.map(w=>`<h3>${esc(name(w))}</h3>${s.locations.filter(l=>l.warehouse===w.id).sort((a,b)=>pathName(s,a.id).localeCompare(pathName(s,b.id))).map(l=>`<div class="hierarchy-node" style="margin-inline-start:${pathName(s,l.id).split(' / ').length*8}px">${icon('warehouses')}<span>${esc(pathName(s,l.id))} <small>· ${t(l.kind)}</small></span><div class="row-actions">${can('location_update')?btn('edit','location_update',l.id):''}</div></div>`).join('')}`).join('')}</div>`)}`;
if(page==='system'){let sys=meta.system;if(!sys)return panel('system',`<p class="notice">${t('permissionHint')}</p>`);return panel('system',`<div class="details"><p>${t('storageHint')}</p><div class="feature-counts"><span>${t(sys.mode)}</span><span>SQLite</span><span>${n(sys.databaseBytes/1024)} ${prefs.lang==='fa'?'کیلوبایت':'KB'}</span></div>${['appPath','dataPath','databasePath','backupPath'].map(k=>`<h3>${t(k)}</h3><p class="storage-path">${esc(sys[k])}</p>`).join('')}<p class="notice">${prefs.lang==='fa'?'پوشه اطلاعات را حذف نکنید. برای جابه‌جایی ابتدا برنامه را متوقف کنید، سپس کل پوشه را کپی کنید. نصب کاربری، برنامه را در پوشه LocalAppData حساب ویندوز شما قرار می‌دهد.':'Do not delete your data folder. Stop the app before moving it. Per-user installation lives in your Windows LocalAppData folder.'}</p><div class="actions">${btn('backup','backup')}${btn('snapshot','snapshot')}</div></div>`)}
if(page==='roadmap'){let counts=features.reduce((s,f)=>((s[f.status]||=[]).push(f),s),{});let summary=`<div class="feature-counts">${Object.entries(counts).map(([k,v])=>`<span>${tag('feature'+k)} ${n(v.length)}</span>`).join('')}</div>`;return summary+panel('roadmap',`<p class="notice">${prefs.lang==='fa'?'این فهرست وضعیت واقعی برنامه را نشان می‌دهد. وجود یک عنوان به معنی تکمیل آن قابلیت نیست.':'This is the actual delivery status. Listing a capability does not mean it is complete.'}</p>`+table(['feature','status','note'],features.map(f=>`<tr><td><b>${esc(f.name[prefs.lang==='fa'?0:1])}</b></td><td>${tag('feature'+f.status)}</td><td>${esc(f.note[prefs.lang==='fa'?0:1])}</td></tr>`)))}
return null}
function dashboardView(ctx){let {state:s,lowTable}=ctx,active=s.products.filter(p=>p.active),needs=new Set(replenishment(s).filter(x=>x.low).map(x=>x.product.id)),zero=active.filter(p=>available(s,p.id)===0).length,reserved=new Set(s.stock.filter(b=>b.reserved>0).map(b=>b.product)).size,purchases=s.orders.filter(o=>o.kind==='purchase'&&!['received','cancelled'].includes(o.status)),sales=s.orders.filter(o=>o.kind==='sales'&&!['dispatched','returned','cancelled'].includes(o.status)),transit=s.transfers.filter(t=>t.status!=='received').length;
const metrics=[['totalProducts',active.length,'products','emphasis'],['lowCount',needs.size,'alerts','warn'],['openOrders',purchases.length+sales.length,'sales',''],['inTransitProducts',transit,'transfers','']];
let days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let key=d.toISOString().slice(0,10),ms=s.movements.filter(m=>m.at.slice(0,10)===key);return {day:new Intl.DateTimeFormat(prefs.lang==='fa'?'fa-IR':'en-GB',{weekday:'short',timeZone:s.settings.timezone}).format(d),in:ms.filter(m=>m.qty>0).length,out:ms.filter(m=>m.qty<0).length}}),max=Math.max(1,...days.flatMap(d=>[d.in,d.out]));
let metricHtml=`<div class="metrics">${metrics.map(([key,value,ico,cls])=>`<article class="metric ${cls}"><span class="symbol">${icon(ico)}</span><label>${t(key)}</label><strong>${n(value)}</strong><small>${t('today')}</small></article>`).join('')}</div>`;
let chart=panel('movement',`<div class="chart">${days.map(d=>`<div class="bars"><i style="height:${d.in/max*85}%" title="${t('inbound')}: ${n(d.in)}"></i><i class="out" style="height:${d.out/max*85}%" title="${t('outbound')}: ${n(d.out)}"></i><em>${d.day}</em></div>`).join('')}</div><div class="legend"><span>${t('inbound')}</span><span>${t('outbound')}</span></div>`,`<span class="tiny">${t('movementHint')}</span>`);
let warehouse=panel('distribution',`<div class="distribution">${s.warehouses.map(w=>{let count=new Set(s.stock.filter(b=>b.warehouse===w.id&&b.qty>0).map(b=>b.product)).size;return `<div class="warehouse-stat"><header><span>${esc(name(w))}</span><b>${n(count)} <small class="muted">${t('product')}</small></b></header><div class="progress"><i style="width:${active.length?count/active.length*100:0}%"></i></div></div>`}).join('')}<div class="insight">${t('reservedProducts')}: <b>${n(reserved)}</b> · ${t('outOfStock')}: <b>${n(zero)}</b></div></div>`);
const tasks=panel('todayWork',`<div class="task-list">${[['incomingOrders',purchases,'purchasing'],['outgoingOrders',sales,'sales']].map(([title,list,page])=>`<div class="task-item"><span><b>${t(title)}</b><small>${n(list.length)} ${t('openOrders')}</small></span><button data-go="${page}">${t('seeAll')} <span>↗</span></button></div>`).join('')}${s.reminders.filter(r=>!r.done).slice(0,2).map(r=>`<div class="task-item"><span><b>${esc(r.name)}</b><small>${date(r.due)}</small></span>${tag('pending')}</div>`).join('')}</div>`);
const recent=panel('recent',`<div class="task-list">${s.movements.slice(0,4).map(m=>`<div class="task-item"><span><b>${esc(name(s.products.find(p=>p.id===m.product)))}</b><small>${t(m.type)} · ${esc(name(s.warehouses.find(w=>w.id===m.warehouse)))}</small></span><span class="tag ${m.qty<0?'warn':''}">${n(m.qty)}</span></div>`).join('')}</div>`);
return metricHtml+`<div class="grid">${chart}${warehouse}</div><div class="grid">${panel('attention',lowTable(),`<button data-go="alerts">${t('seeAll')} ↗</button>`)}${tasks}</div>`+recent}
export function extraForm(kind,arg,ctx){const {state:s,mutate,can}=ctx,ws=s.warehouses.map(w=>[w.id,name(w)]),ps=s.products.filter(p=>p.active).map(p=>[p.id,name(p)+' · '+p.sku]),layers=s.stock.filter(b=>b.qty-b.reserved>0).map(b=>[b.id,name(s.products.find(p=>p.id===b.product))+' · '+name(s.warehouses.find(w=>w.id===b.warehouse))+' · '+(b.lot||b.serial||pathName(s,b.location))+' · '+n(b.qty-b.reserved)]);
if(kind==='location'||kind==='location_update'){let l=kind==='location_update'?s.locations.find(l=>l.id===arg):{};let html=select('warehouse',ws,l.warehouse||ws[0]?.[0])+select('kind',['zone','aisle','rack','shelf','bin'].map(k=>[k,t(k)]),l.kind||'bin')+field('name','text',l.name||'')+field('en','text',l.en||'',false)+select('parent',[['','—'],...s.locations.filter(x=>x.warehouse===(l.warehouse||ws[0]?.[0])&&x.id!==l.id).map(x=>[x.id,pathName(s,x.id)])],l.parent||'');let d=show(kind==='location'?'newLocation':'edit',html,b=>mutate({...b,type:kind,...(l.id?{id:l.id,expectedRecordVersion:l._revision||0}:{})}));if(l.id)d.querySelector('[name=warehouse]').disabled=true;const w=d.querySelector('[name=warehouse]');w.onchange=()=>{d.querySelector('[name=parent]').innerHTML='<option value="">—</option>'+s.locations.filter(x=>x.warehouse===w.value&&x.id!==l.id).map(x=>`<option value="${x.id}">${esc(pathName(s,x.id))}</option>`).join('')};if(l.id)d.querySelector('form').onsubmit=((fn)=>async e=>{w.disabled=false;try{await fn(e)}finally{w.disabled=true}})(d.querySelector('form').onsubmit);return true}
if(kind==='bin_move'){let initial=s.stock.find(b=>b.id===arg)||s.stock.find(b=>b.qty-b.reserved>0);let d=show(kind,select('layer',layers,initial?.id)+field('qty','number',1)+select('location',s.locations.filter(l=>l.warehouse===initial?.warehouse&&l.id!==initial?.location).map(l=>[l.id,pathName(s,l.id)])),b=>mutate({...b,type:kind}));d.querySelector('[name=layer]').onchange=e=>{let b=s.stock.find(b=>b.id===e.target.value);d.querySelector('[name=location]').innerHTML=s.locations.filter(l=>l.warehouse===b.warehouse&&l.id!==b.location).map(l=>`<option value="${l.id}">${esc(pathName(s,l.id))}</option>`).join('')};return true}
if(kind==='supplier_return'){show(kind,select('layer',layers,arg||layers[0]?.[0])+select('supplier',s.contacts.filter(c=>c.type==='supplier').map(c=>[c.id,c.name]))+field('qty','number',1)+area('reason','', 'required'),b=>mutate({...b,type:kind}));return true}
if(kind==='reorder_rule'){let [product,warehouse]=arg?.split('|')||[],rule=s.reorderRules.find(r=>r.product===product&&(!warehouse||r.warehouse===warehouse))||{};show('ruleNew',select('product',ps,product||ps[0]?.[0])+select('warehouse',ws,warehouse||rule.warehouse||ws[0]?.[0])+field('min','number',rule.min??0)+field('target','number',rule.target??0)+field('safety','number',rule.safety??0)+field('leadDays','number',rule.leadDays??0)+select('supplier',[['','—'],...s.contacts.filter(c=>c.type==='supplier').map(c=>[c.id,c.name])],rule.supplier),b=>mutate({...b,type:kind,expectedRecordVersion:rule._revision||0}),true);return true}
if(kind==='unit_conversion'){let p=s.products.find(p=>p.id===arg);show('conversion',`<p class="notice full">${esc(name(p))} · ${t('baseUnit')}: ${esc(name(s.units.find(u=>u.code===p.unit)))}</p>`+select('unit',s.units.filter(u=>u.code!==p.unit).map(u=>[u.code,name(u)]))+field('factor','number',1),b=>mutate({...b,type:kind,product:p.id}));return true}
if(kind==='saveReport'){show('saveView',field('name'),b=>mutate({type:'saved_report',name:b.name,filters:ctx.filter}));return true}
return false}
